def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    prev_need_bids = []
    max_opp_budget = 0.0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) > max_opp_budget:
                max_opp_budget = opp.get('budget', 0)
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = prev.get('bid', 0)
                prev_bids.append(bid)
                if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                    prev_need_bids.append(bid)

    if not alive:
        return max(0.0, min(budget, DAILY_SALARY * 0.2))

    slots = max(1, int(supply // WATER_REQ))
    total_alive = len(alive) + 1
    scarcity = total_alive - slots

    highest_prev = max(prev_bids) if prev_bids else 0.0
    urgent_prev = max(prev_need_bids) if prev_need_bids else highest_prev

    if hp <= 2 or no_water_days >= 2:
        bid = max(DAILY_SALARY * 1.05, urgent_prev + 3.0)
    elif hp <= 4 or no_water_days >= 1:
        if scarcity >= 2:
            bid = max(DAILY_SALARY * 0.92, highest_prev + 2.0)
        else:
            bid = max(DAILY_SALARY * 0.72, highest_prev * 0.9)
    else:
        if scarcity >= 3:
            bid = max(DAILY_SALARY * 0.9, highest_prev + 1.5)
        elif scarcity >= 2:
            bid = max(DAILY_SALARY * 0.72, highest_prev * 0.82)
        elif scarcity >= 1:
            bid = max(DAILY_SALARY * 0.52, highest_prev * 0.68)
        else:
            bid = DAILY_SALARY * 0.35

    if highest_prev >= 120:
        if hp >= 5 and no_water_days == 0:
            bid = min(bid, DAILY_SALARY * 0.45)
        else:
            bid = max(bid, DAILY_SALARY * 0.88)

    if max_opp_budget < budget * 0.6 and scarcity >= 2:
        bid = max(bid, highest_prev + 1.0)

    if budget < DAILY_SALARY * 2:
        if hp >= 5 and no_water_days == 0:
            bid = min(bid, DAILY_SALARY * 0.4)
        else:
            bid = min(bid, budget)

    bid = max(0.0, min(budget, bid))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    # Alive opponents
    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive.append((oid, o))

    if not alive:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Extract yesterday bids for immediate reaction
    prev_bids = []
    prev_by_id = {}
    for oid, o in alive:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                bval = float(b)
                prev_bids.append(bval)
                prev_by_id[oid] = bval
            except Exception:
                pass

    # If we can't read bids, use a conservative default
    if not prev_bids:
        base = DAILY_SALARY * (0.55 if my_status['hp'] > 2 else 0.9)
        return float(min(my_status['budget'], base))

    highest_prev_bid = max(prev_bids)
    second_prev_bid = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else highest_prev_bid

    # Pressure estimate: if someone was willing to pay near/above ~salary, expect aggressive bidding.
    aggressive = highest_prev_bid >= (DAILY_SALARY * 0.85)

    # Supply-based escalation: with higher supply, we can safely outbid slightly less.
    # Map supply to a multiplier in [0.8, 1.2]
    if MAX_SUPPLY > MIN_SUPPLY:
        t = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        t = 0.5
    if t < 0.0:
        t = 0.0
    if t > 1.0:
        t = 1.0
    supply_mult = 0.8 + 0.4 * t

    # Our urgency
    hp = int(my_status.get('hp', 0))
    no_water_days = int(my_status.get('no_water_days', 0))
    urgent = (hp <= 2) or (no_water_days >= 2)

    # Core strategy:
    # - If aggressive yesterday, target just above the likely second bidder to secure water.
    # - Otherwise, bid around a mid fraction to conserve budget.
    if aggressive:
        # Bid slightly above second highest to avoid overpaying while still beating most.
        target = second_prev_bid + 2.0
        # If we are very urgent, increase to ensure we win.
        if urgent:
            target = max(target, highest_prev_bid * 0.98)
        target *= supply_mult
    else:
        # Conservative: aim to be competitive but not maximal.
        if urgent:
            target = DAILY_SALARY * 0.85 * supply_mult
        else:
            # If supply is high, can bid lower and still win due to reduced competition.
            target = DAILY_SALARY * (0.45 + 0.1 * t) * supply_mult

        # Also cap relative to previous highest to avoid runaway spending.
        target = min(target, highest_prev_bid + 5.0)

    # Final safety: cannot exceed budget; also keep non-negative
    budget = float(my_status.get('budget', 0.0))
    bid = float(target)
    if bid < 0.0:
        bid = 0.0
    if bid > budget:
        bid = budget

    # If budget is extremely low, spend enough to survive this day if possible
    if budget <= DAILY_SALARY * 0.2:
        # Prefer to bid near the budget to avoid immediate death.
        bid = budget

    return float(bid)

